EXEC model.put_semantic_definition 'PROVIDER',N'sidefx:providers',N'ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform',N'{"capabilities":[{"capabilityId":"sda-fixture-contract-validator.v1","conformanceRef":"tools/tests/consumer-projection/csharp-consumer-projection.test.js","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"contract-validator","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["contract-validation"],"status":"ADMITTED"},{"capabilityId":"sda-declarative-value-port.v1","conformanceRef":"tools/tests/consumer-projection/csharp-consumer-projection.test.js","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"event-port","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["event-port-invocation"],"status":"ADMITTED"},{"capabilityId":"sda-declarative-state-projection.v1","conformanceRef":"tools/tests/consumer-projection/csharp-consumer-projection.test.js","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"state-projection","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["state-projection"],"status":"ADMITTED"},{"capabilityId":"sda-csharp-admitted-consumer-platform.v1","conformanceRef":"languages/csharp/tests/ScenarioKernel.ConformanceTests/AdapterConformanceTests.cs","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"consumer-runtime","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["scenario-orchestration","contract-document-reading","canonicalization","schema-admission","authority-resolution","semantic-execution","telemetry-observation","scenario-invocation","transition-binding-projection","interface-delivery","runtime-projection","artifact-result-delivery","authority-driven-transformation","durable-artifact-materialization"],"status":"ADMITTED"},{"capabilityId":"sda-json-cli.v1","conformanceRef":"languages/csharp/tests/ScenarioKernel.ConformanceTests/AdapterConformanceTests.cs","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"interface-delivery","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["cli-delivery","json-reading","json-serialization"],"status":"ADMITTED"},{"capabilityId":"sda-csharp-sdk.v1","conformanceRef":"languages/csharp/tests/ScenarioKernel.ConformanceTests/AdapterConformanceTests.cs","implementationRef":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/AdmittedConsumerPlatform.cs","kind":"interface-delivery","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["sdk-delivery","declared-query-evaluation","json-reading","json-serialization"],"status":"ADMITTED"},{"capabilityId":"sda-external-credential-reference-binding-port.v1","conformanceRef":"sha256:316fe5f7b5c42f4f14ba78a8943b5b20d78771cf54011252fda9be8a5250aa4c","implementationRef":"sha256:778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9","kind":"event-port","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["event-port-invocation","external-credential-reference-binding","one-use-opaque-credential-handle","secret-non-disclosure"],"status":"ADMITTED","hostProvider":"ScenarioKernel.NodePlatform.Effects.ExternalCredentialReferenceBinding","hostImplementationRef":"languages/typescript/runtimes/node/external-credential-reference-binding-provider.mjs","hostImplementationDigest":"sha256:415806ff8d181e9cf4d87814b3c2f40fb39d598e236877c66d88e521726371df","hostProviderExport":"bindExternalCredentialReference"},{"capabilityId":"sda-governed-http-exchange-port.v1","conformanceRef":"sha256:316fe5f7b5c42f4f14ba78a8943b5b20d78771cf54011252fda9be8a5250aa4c","implementationRef":"sha256:778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9","kind":"event-port","projectionTarget":"csharp","provider":"ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform","providesMechanics":["event-port-invocation","single-governed-http-exchange","bounded-response-observation","credential-injection-without-disclosure"],"status":"ADMITTED","hostProvider":"ScenarioKernel.NodePlatform.Effects.GovernedHttpExchange","hostImplementationRef":"languages/typescript/runtimes/node/governed-http-exchange-provider.mjs","hostImplementationDigest":"sha256:67a28e738ade419a256b85c9bc139d1aad0f256d196b28250465d763845a2e5f","hostProviderExport":"observeGovernedHttpExchange"}],"catalogType":"sda-platform-capability-catalog.v1","executionAuthority":{"target":"csharp","pinnedPlatformCommit":"716811046f52dd2a67f9ff308a50d755571cbbad","effectContext":{"module":"languages/typescript/runtimes/node/native-mechanic-primitives.mjs","export":"createGovernedEffectContext","digest":"sha256:1cc204869f0ce7b60ad03187d364db4a432b0b632ce4469a7cf37747d6a379d5"},"runtime":{"command":"dotnet","args":["{estateRoot}/providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ConsumerExecution.dll"],"source":"using System.Text.Json;\nusing System.Text.Json.Nodes;\nusing ScenarioKernel.Adapters.Consumer;\nusing ScenarioKernel.Adapters.Graph;\n\nvar request = JsonNode.Parse(Console.ReadLine()!)!.AsObject();\nvar plan = request[\"plan\"]!.AsObject();\nvar root = request[\"input\"];\nvar physical = request[\"physicalCellIds\"]!.AsArray().Select(x => x!.GetValue<string>()).ToHashSet(StringComparer.Ordinal);\nvar collections = new Dictionary<string, int>(StringComparer.Ordinal);\nvar engine = new SemanticTransformationEngine();\nvar cells = plan[\"canonicalGraph\"]![\"cells\"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x[\"cellId\"]!.GetValue<string>(), StringComparer.Ordinal);\nasync ValueTask<GraphProviderOutcome> Provider(JsonNode? input, GraphExecutionContext context, CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();\n    if (physical.Contains(context.CellId))\n    {\n        Console.WriteLine(new JsonObject {\n            [\"type\"] = \"invoke-provider\", [\"cellId\"] = context.CellId,\n            [\"cellExecutionId\"] = context.CellExecutionId, [\"rootExecutionId\"] = context.RootExecutionId,\n            [\"input\"] = input?.DeepClone()\n        }.ToJsonString());\n        var reply = JsonNode.Parse((await Console.In.ReadLineAsync(token))!)!.AsObject();\n        if (reply[\"error\"] is JsonValue error) throw new InvalidOperationException(error.GetValue<string>());\n        return new GraphProviderOutcome(reply[\"outcome\"]?.DeepClone());\n    }\n    var expression = context.Configuration?[\"binding\"]?[\"configuration\"]?[\"expression\"] as JsonObject ?? context.Configuration;\n    if (expression?[\"op\"] is not JsonValue operation)\n    {\n        if (cells[context.CellId][\"execution\"]?[\"authorityId\"]?.GetValue<string>() == \"mechanic:identity.v1\") return new GraphProviderOutcome(input?.DeepClone(), \"VALUE\");\n        throw new InvalidOperationException(\"UNDECLARED_EXECUTION_MECHANIC:\" + context.CellId);\n    }\n    try\n    {\n        var entering = context.DecompositionInput ?? input;\n        var outcome = engine.Transform(expression, entering, root);\n        if (outcome is null) throw new InvalidOperationException(\"LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE\");\n        if (new[] { \"map\", \"flat-map\", \"filter\", \"find\", \"some\", \"every\" }.Contains(operation.GetValue<string>(), StringComparer.Ordinal))\n        {\n            var occurrence = collections.GetValueOrDefault(context.CellId);\n            collections[context.CellId] = occurrence + 1;\n            var source = expression[\"from\"] is JsonObject from ? engine.Transform(from, entering, root) as JsonArray : null;\n            return new GraphProviderOutcome(outcome, occurrence < (source?.Count ?? 0) ? \"CONTINUE\" : \"STOP\");\n        }\n        return new GraphProviderOutcome(outcome);\n    }\n    catch (InvalidOperationException)\n    {\n        return new GraphProviderOutcome(input?.DeepClone(), \"VALUE\");\n    }\n}\nvar authorities = plan[\"bindingAuthorities\"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x[\"id\"]!.GetValue<string>(), StringComparer.Ordinal);\nValueTask<JsonNode?> ProjectBinding(string identity, JsonNode? value, CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();\n    return ValueTask.FromResult(engine.Transform(authorities[identity][\"binding\"]![\"configuration\"]![\"expression\"]!.AsObject(), value, root));\n}\nvar providers = plan[\"realizationOverlay\"]![\"providerBindings\"]!.AsArray()\n    .Select(x => x![\"providerProfileId\"]!.GetValue<string>()).Distinct(StringComparer.Ordinal)\n    .ToDictionary(identity => identity, _ => (GraphProvider)Provider, StringComparer.Ordinal);\nvar result = await new SemanticExecutionGraphScheduler(plan, providers, ProjectBinding).ExecuteAsync(root, request[\"rootExecutionId\"]!.GetValue<string>());\nConsole.WriteLine(new JsonObject { [\"type\"] = \"result\", [\"result\"] = result }.ToJsonString());\n","sourceDigest":"sha256:778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9","dependencies":[{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ConsumerExecution.deps.json","digest":"sha256:ecf470605df840980934099a537ced554cda569ce2c7cdc84dd5e4432dc6c6a3"},{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ConsumerExecution.dll","digest":"sha256:fd72f16e14cd51249e39562ba3f6abfdb11ae5ecb4da75167332771f2d85640d"},{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ConsumerExecution.runtimeconfig.json","digest":"sha256:256dda2706e1151bb95987b6b5be610bf68d64e058285b19e7e958222fc90414"},{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ScenarioKernel.Adapters.dll","digest":"sha256:5958b088f53e19370ab9e08cf764789f0cd4be45fc158a144a5d33296ade0ef4"},{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ScenarioKernel.Contracts.dll","digest":"sha256:2ee3332365aab74bd6e15413e08519d2dc81b22397a39f3cdb4b2ececb2b6ddf"},{"root":"estateRoot","path":"providers/consumer-execution/778eb8902e06c9d2b0ed1f393a8cadf2bde91df16de16cd74d01cdaf87b20ae9/ScenarioKernel.Execution.dll","digest":"sha256:356e3a55eed08760f25eaa74a77e0b764900659d3a62c5bf5cbcd7e8717b62ec"},{"root":"sdaRoot","path":"languages/csharp/src/ScenarioKernel.Adapters/Graph/SemanticExecutionGraphScheduler.cs","digest":"sha256:e1ae899393c78b6e179d9a5300f94d7617cf043b0e0c6f85ee4b84f24ab3f8ca"},{"root":"sdaRoot","path":"languages/csharp/src/ScenarioKernel.Adapters/Consumer/SemanticTransformationEngine.cs","digest":"sha256:fd67dd950b66ce60933f3027f5f4001e52883622d94549231121aafcbf4c0e93"}],"timeoutMilliseconds":60000,"maximumOutputBytes":16777216,"environment":{}}}}',@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
DECLARE @provider bigint=(SELECT provider_pk FROM model.provider WHERE semantic_object_pk=@object);
DECLARE @provider_definition bigint=(SELECT provider_definition_pk FROM model.provider_definition WHERE semantic_object_definition_pk=@definition);
IF @provider_definition IS NULL BEGIN
 INSERT model.provider_definition(provider_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,name,declaration_profile,object_kind,_owner_definition_pk,_canonical_pointer)
 VALUES(@provider,@object,@definition,@digest,N'ScenarioKernel.Adapters.Consumer.AdmittedConsumerPlatform','sda-platform-capability-catalog.v1','PROVIDER',@definition,N'');
 SET @provider_definition=SCOPE_IDENTITY();
END;
INSERT model.provider_capability_implementation(provider_definition_pk,capability_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @provider_definition,capability_version_pk,role,@definition,_canonical_pointer FROM model.provider_capability_implementation i
WHERE provider_definition_pk=@previous AND NOT EXISTS(SELECT 1 FROM model.provider_capability_implementation n WHERE n.provider_definition_pk=@provider_definition AND n.capability_version_pk=i.capability_version_pk);
INSERT model.provider_mechanic_implementation(provider_definition_pk,mechanic_version_pk,provider_profile_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @provider_definition,mechanic_version_pk,provider_profile_version_pk,role,@definition,_canonical_pointer FROM model.provider_mechanic_implementation i
WHERE provider_definition_pk=@previous AND NOT EXISTS(SELECT 1 FROM model.provider_mechanic_implementation n WHERE n.provider_definition_pk=@provider_definition AND n.mechanic_version_pk=i.mechanic_version_pk AND (n.provider_profile_version_pk=i.provider_profile_version_pk OR n.provider_profile_version_pk IS NULL AND i.provider_profile_version_pk IS NULL));
INSERT model.provider_capability_implementation(provider_definition_pk,capability_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT @provider_definition,ec.capability_version_pk,'PLATFORM',@definition,N'' FROM model.capability c
JOIN model.identity_namespace n ON n.namespace_pk=c.namespace_pk AND n.namespace_id=N'sidefx:platform-capabilities'
JOIN model.estate_capability ec ON ec.capability_pk=c.capability_pk JOIN source.current_model cm ON cm.estate_model_pk=ec.estate_model_pk
WHERE c.capability_id IN (N'sda-external-credential-reference-binding-port.v1',N'sda-governed-http-exchange-port.v1') AND NOT EXISTS(SELECT 1 FROM model.provider_capability_implementation i WHERE i.provider_definition_pk=@provider_definition AND i.capability_version_pk=ec.capability_version_pk);
SELECT N'csharp' AS target,@provider_definition AS provider_definition_pk;
GO

DECLARE @selected_model bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
SELECT * INTO #implementations FROM analysis.v_target_provider_implementation WHERE estate_model_pk=@selected_model;
SELECT * INTO #profiles FROM analysis.v_target_provider_profile WHERE estate_model_pk=@selected_model;
SELECT pv.port_version_pk,d.definition_json INTO #ports
FROM model.port_version pv JOIN analysis.v_selected_semantic_definition d
 ON d.semantic_object_definition_pk=pv.semantic_object_definition_pk AND d.estate_model_pk=@selected_model
WHERE EXISTS (SELECT 1 FROM model.slot_port_requirement r WHERE r.port_version_pk=pv.port_version_pk);
INSERT model.provider_port_implementation
 (provider_definition_pk,port_version_pk,provider_profile_version_pk,role,_owner_definition_pk,_canonical_pointer)
SELECT DISTINCT i.provider_definition_pk,r.port_version_pk,p.provider_profile_version_pk,
 r.role,i.semantic_object_definition_pk,N''
FROM model.slot_port_requirement r JOIN #ports d ON d.port_version_pk=r.port_version_pk
JOIN #implementations i ON i.capability_id=JSON_VALUE(d.definition_json,'$.semantics.platformCapabilityId')
JOIN #profiles p ON p.target_id=i.target_id AND p.effect_classification='effect'
WHERE NOT EXISTS (SELECT 1 FROM model.provider_port_implementation existing
 WHERE existing.provider_definition_pk=i.provider_definition_pk AND existing.port_version_pk=r.port_version_pk
 AND existing.provider_profile_version_pk=p.provider_profile_version_pk);
SELECT 'port_implementations_added' AS result_set,@@ROWCOUNT AS added;

SELECT * INTO #candidates FROM analysis.v_provider_slot_candidate WHERE estate_model_pk=@selected_model;
INSERT model.provider_binding
 (provider_binding_scope_pk,provider_slot_pk,selection_policy,provider_definition_pk,ordinal,_owner_definition_pk,_canonical_pointer)
SELECT scope.provider_binding_scope_pk,scope.provider_slot_pk,scope.selection_policy,
 candidate.provider_definition_pk,NULL,scope._owner_definition_pk,scope._canonical_pointer
FROM model.provider_binding_scope scope
JOIN model.binding_context context ON context.binding_context_pk=scope.binding_context_pk
JOIN #candidates candidate ON candidate.provider_slot_pk=scope.provider_slot_pk
 AND candidate.provider_profile_version_pk=context.provider_profile_version_pk
WHERE scope.selection_policy='SINGLE'
 AND (SELECT COUNT(*) FROM #candidates c WHERE c.provider_slot_pk=scope.provider_slot_pk
      AND c.provider_profile_version_pk=context.provider_profile_version_pk)=1
 AND NOT EXISTS (SELECT 1 FROM model.provider_binding b WHERE b.provider_binding_scope_pk=scope.provider_binding_scope_pk);
SELECT 'bindings_added' AS result_set,@@ROWCOUNT AS added;

INSERT model.binding_port_implementation
 (provider_binding_pk,provider_slot_pk,slot_port_requirement_pk,port_version_pk,
  provider_definition_pk,provider_port_implementation_pk,_owner_definition_pk,_canonical_pointer)
SELECT b.provider_binding_pk,b.provider_slot_pk,r.slot_port_requirement_pk,r.port_version_pk,
 b.provider_definition_pk,i.provider_port_implementation_pk,b._owner_definition_pk,b._canonical_pointer
FROM model.provider_binding b
JOIN model.provider_binding_scope scope ON scope.provider_binding_scope_pk=b.provider_binding_scope_pk
JOIN model.binding_context context ON context.binding_context_pk=scope.binding_context_pk
JOIN model.slot_port_requirement r ON r.provider_slot_pk=b.provider_slot_pk
JOIN model.provider_port_implementation i ON i.provider_definition_pk=b.provider_definition_pk
 AND i.port_version_pk=r.port_version_pk AND i.provider_profile_version_pk=context.provider_profile_version_pk
WHERE NOT EXISTS (SELECT 1 FROM model.binding_port_implementation existing
 WHERE existing.provider_binding_pk=b.provider_binding_pk AND existing.slot_port_requirement_pk=r.slot_port_requirement_pk);


SELECT 'equity_slot_resolution' AS result_set,slot_id,target_id,candidate_count,binding_count,disposition FROM analysis.v_provider_slot_resolution
WHERE estate_model_pk=@selected_model AND capability_id='resolve-equity-market-price-evidence' ORDER BY target_id,slot_id;
GO
-- A complete binding set still declares empty collections.
DECLARE @estate bigint=(SELECT estate_model_pk FROM source.current_model WHERE singleton_id=1);
DECLARE @semantics nvarchar(max),@statement nvarchar(max),@old_version bigint,@port bigint;
SELECT @semantics=JSON_QUERY(d.definition_json,'$.semantics'),@old_version=pv.port_version_pk,@port=pv.port_pk
FROM analysis.v_selected_semantic_definition d JOIN model.port_version pv ON pv.semantic_object_definition_pk=d.semantic_object_definition_pk
WHERE d.estate_model_pk=@estate AND d.object_kind='PORT' AND d.namespace_id=N'sidefx:capability:resolve-provider-slot-bindings'
 AND d.declared_id=N'resolve-provider-slot-bindings-port';
SELECT @statement=statement FROM OPENJSON(@semantics,'$.configuration') WITH(statement nvarchar(max) '$.statement');
IF @statement IS NULL THROW 51000,'BINDING_RESOLVER_STATEMENT_ABSENT',1;
IF CHARINDEX(N'JSON_QUERY(COALESCE((SELECT',@statement)=0 BEGIN
 SET @statement=REPLACE(@statement,N'JSON_QUERY((SELECT',N'JSON_QUERY(COALESCE((SELECT');
 SET @statement=REPLACE(@statement,N'FOR JSON PATH)) AS',N'FOR JSON PATH),N''[]'')) AS');
END;
SET @semantics=JSON_MODIFY(@semantics,'$.configuration.statement',@statement);
DECLARE @object bigint,@definition bigint,@digest binary(32);
EXEC model.put_semantic_definition 'PORT',N'sidefx:capability:resolve-provider-slot-bindings',N'resolve-provider-slot-bindings-port',
 @semantics,@object OUTPUT,@definition OUTPUT,@digest OUTPUT;
DECLARE @version bigint=(SELECT port_version_pk FROM model.port_version WHERE semantic_object_definition_pk=@definition);
IF @version IS NULL BEGIN
 INSERT model.port_version(port_pk,semantic_object_pk,semantic_object_definition_pk,definition_digest,port_profile,object_kind,_owner_definition_pk,_canonical_pointer)
 VALUES(@port,@object,@definition,@digest,'consumer-interface-authority.v1','PORT',@definition,N'');
 SET @version=SCOPE_IDENTITY();
END;
UPDATE model.operation_port_invocation SET port_version_pk=@version WHERE port_version_pk=@old_version;
SELECT 'binding_result_collections' AS result_set,@version AS port_version_pk;
COMMIT TRANSACTION;
